import { useEffect, useState } from "react";
import { extractErrorMessage } from "../api/axios";

/**
 * Loads API records and converts them into select options.
 *
 * Supports backend responses such as:
 *
 * 1. [ ... ]
 * 2. { data: [ ... ] }
 * 3. { data: { students: [ ... ] } }
 * 4. { students: [ ... ] }
 * 5. { items: [ ... ] }
 * 6. { courses: [ ... ] }
 * 7. { departments: [ ... ] }
 *
 * mapper converts each record into:
 *
 * {
 *   value: "...",
 *   label: "..."
 * }
 */
export function useLookupOptions(fetchFn, mapper) {
  const [options, setOptions] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    let isCurrent = true;

    async function loadOptions() {
      setIsLoading(true);
      setError("");

      try {
        const response = await fetchFn();

        if (!isCurrent) return;

        const responseData = response?.data;

        let list = [];

        // Backend returns an array directly
        if (Array.isArray(responseData)) {
          list = responseData;
        }

        // Backend returns { data: [...] }
        else if (Array.isArray(responseData?.data)) {
          list = responseData.data;
        }

        // Backend returns { data: { students: [...] } }
        else if (Array.isArray(responseData?.data?.students)) {
          list = responseData.data.students;
        }

        // Backend returns { data: { courses: [...] } }
        else if (Array.isArray(responseData?.data?.courses)) {
          list = responseData.data.courses;
        }

        // Backend returns { data: { departments: [...] } }
        else if (Array.isArray(responseData?.data?.departments)) {
          list = responseData.data.departments;
        }

        // Backend returns { students: [...] }
        else if (Array.isArray(responseData?.students)) {
          list = responseData.students;
        }

        // Backend returns { courses: [...] }
        else if (Array.isArray(responseData?.courses)) {
          list = responseData.courses;
        }

        // Backend returns { departments: [...] }
        else if (Array.isArray(responseData?.departments)) {
          list = responseData.departments;
        }

        // Backend returns { items: [...] }
        else if (Array.isArray(responseData?.items)) {
          list = responseData.items;
        }

        const mappedOptions = list
          .map((item) => {
            try {
              return mapper(item);
            } catch {
              return null;
            }
          })
          .filter(
            (option) =>
              option &&
              option.value !== undefined &&
              option.value !== null
          );

        setOptions(mappedOptions);
      } catch (err) {
        if (!isCurrent) return;

        setOptions([]);
        setError(
          extractErrorMessage(
            err,
            "Unable to load options."
          )
        );
      } finally {
        if (isCurrent) {
          setIsLoading(false);
        }
      }
    }

    loadOptions();

    return () => {
      isCurrent = false;
    };
  }, [fetchFn, mapper]);

  return {
    options,
    isLoading,
    error
  };
}
